package com.bananalab.lite;
import java.util.*;
public final class Stage41KissCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static BananaEngine.Result run(CreatorPersistenceCheck.Fake c,Semilla m,String q)throws Exception{return BananaEngine.run(c,q,new ArrayList<String[]>(),"",true,m);}
 public static void main(String[] args)throws Exception{String root=args[0];Semilla m=SemillaCheck.load(root+"/assets/language");CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();BananaEngine.Result r=run(c,m,"que el zorro bese a la banana");check(r.changed&&r.scene.cast.size()==2,"exact reported request creates both actors");SceneDraft d=r.scene;check(d.actions.contains("besa")&&d.actions.contains("recibebeso")&&d.actions.contains("acercaactor"),"explicit approach and paired kiss");int i=d.actions.indexOf("besa");check(d.cast.get(d.actors.get(i)).kind.equals("zorro")&&d.get(d.recipient(i)).kind.equals("banana"),"correct actor and recipient");check(SceneConsistency.problem(d)==null,"valid paired action");float time=(d.slot(i)+.5f)/ObjectTransfer.beats(d);String a=d.cast.get(d.actors.get(i)).name,b=d.recipient(i);float[] pa=KissMotion.pose(d,a,time),pb=KissMotion.pose(d,b,time),ma=KissMotion.mouth(d.get(a),KissMotion.direction(d,a,i)),mb=KissMotion.mouth(d.get(b),KissMotion.direction(d,b,i));float[] wa=ActorGeometry.world(ma[0],ma[1],pa),wb=ActorGeometry.world(mb[0],mb[1],pb);check(Math.hypot(wa[0]-wb[0],wa[1]-wb[1])<.0001,"actual shared face contact, not just hearts at a distance");check(KissMotion.envelope(0)==0&&KissMotion.envelope(1)==0,"contact returns to stance");SceneDraft restored=SceneDraft.read(d.json().toString());check(restored.recipient(i).equals(b),"saved scene retains kiss target");String id=d.get(a).designId;run(c,m,"continua con la banana saluda");r=run(c,m,"el zorro besa a la banana");check(r.changed&&r.scene.get(a).designId.equals(id)&&r.scene.actions.contains("saluda"),"kiss appends and preserves designs and earlier actions");String before=SceneStore.load(c).json().toString();r=run(c,m,"el zorro besa al zorro");check(!r.changed&&before.equals(SceneStore.load(c).json().toString()),"invalid self target is atomic");r=run(c,m,"el zorro besa a una jirafa");check(!r.changed&&before.equals(SceneStore.load(c).json().toString()),"unsupported recipient is not replaced by another actor");
  CreatorPersistenceCheck.Fake names=new CreatorPersistenceCheck.Fake();run(names,m,"crea a Fito un zorro; agrega una banana llamada Bani");r=run(names,m,"Fito le da un beso a Bani");check(r.changed&&r.scene.actions.contains("besa"),"named actors and dar un beso paraphrase");run(names,m,"planea: Fito besa a Bani; continua con Bani saluda");r=run(names,m,"aplica el plan");check(r.changed&&r.scene.actions.contains("saluda"),"new action supported in mobile plan");
  SceneDraft broken=d.copy();int receiving=broken.actions.indexOf("recibebeso");broken.actions.set(receiving,"espera");check(SceneConsistency.problem(broken)!=null,"orphan kiss rejected");d.get(a).size=.6f;d.get(b).size=1.4f;pa=KissMotion.pose(d,a,time);pb=KissMotion.pose(d,b,time);wa=ActorGeometry.world(ma[0],ma[1],pa);wb=ActorGeometry.world(mb[0],mb[1],pb);check(Math.hypot(wa[0]-wb[0],wa[1]-wb[1])<.0001,"contact accounts for different actor sizes");System.out.println("PASS Stage41 reported kiss request, correct paired actors, actual contact, persistence, aliases, plan integration, atomic invalid targets and size-aware geometry");}
}
